/**
 * An operations view in the org's own brand: a theme (theme.ts) with a bundled font, dense spacing,
 * subtle motion and its own elevation, a heatmap of a metric grouped by two dimensions, and a gauge against a target. Each chart reads
 * one governed metric; the theme follows the host's light or dark mode.
 */
import { createRoot } from 'react-dom/client';
import { ChartGauge, ChartHeatmap, EmptyState, Section, Skeleton, SurfaceApp, useMetric } from '@cynap/surface-sdk';

import { theme } from './theme';
import './styles.css';

/**
 * The heatmap metric must be authored grouped by two dimensions; the gauge metric is one number.
 * Replace both, and the target.
 */
const ACTIVITY_METRIC = 'REPLACE_WITH_ACTIVITY_METRIC';
const TARGET_METRIC = 'REPLACE_WITH_TARGET_METRIC';
const TARGET_VALUE = 100;

type Row = Record<string, unknown>;
const valueOf = (row: Row) => (typeof row.value === 'number' ? row.value : Number(row.value) || 0);

/** A two-dimension metric row is `{label: "<x> / <y>", value}`: split the label into the two axes. */
function toCells(rows: readonly Row[]): Row[] {
  return rows.map((row) => {
    const [x = '(none)', y = '(none)'] = String(row.label ?? '').split(' / ');
    return { x, y, value: valueOf(row) };
  });
}

function Ops() {
  const activity = useMetric(ACTIVITY_METRIC);
  const target = useMetric(TARGET_METRIC);
  const activityRows = toCells(activity.data?.rows ?? []);
  const targetRows = [...(target.data?.rows ?? [])];

  return (
    <main className="tpl-page">
      <Section title="Operations">
        {activityRows.length > 0 ? (
          <ChartHeatmap xAxisKey="x" yAxisKey="y" valueKey="value" emptyCellTreatment="zero" data={activityRows} title="Activity" />
        ) : (
          activity.state === 'loading' ? <Skeleton primitiveKind="Chart.Heatmap" height={240} /> : <EmptyState title="No activity yet" />
        )}
        {targetRows.length > 0 && (
          <ChartGauge valueKey="value" targetValue={TARGET_VALUE} min={0} max={TARGET_VALUE * 1.5} data={targetRows} title="Against target" />
        )}
      </Section>
    </main>
  );
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'themed-ops', version: '1.0.0' }} theme={theme}>
      <Ops />
    </SurfaceApp>
  );
}

