/**
 * The bundle's theme: the one file allowed to hold colour literals. Each key overrides the host's
 * value for that polarity; a key left out keeps the host's. Replace the values with the brand's.
 * The font is a static import of a file in this surface (add brand-sans.woff2 beside this file):
 * the SDK registers it and names its family, so there is no font rule to write.
 */
import { defineSurfaceTheme } from '@cynap/surface-sdk';

import brandSans from './brand-sans.woff2';

export const theme = defineSurfaceTheme({
  fonts: { sans: brandSans },
  density: 'compact',
  motion: 'subtle',
  light: {
    '--color-background-primary': '#ffffff',
    '--color-text-primary': '#14213d',
    '--color-ring-primary': '#2a9d8f',
    '--border-radius-md': '10px',
    '--shadow-sm': '0 1px 2px rgb(20, 33, 61, 0.08)',
    '--shadow-md': '0 0 0 1px #14213d1a, 0 4px 12px rgb(20, 33, 61, 0.12)',
    '--chart-1': '#2a9d8f',
  },
  dark: {
    '--color-background-primary': '#0b132b',
    '--color-text-primary': '#e9edf5',
    '--color-ring-primary': '#4cc9b0',
    '--border-radius-md': '10px',
    '--shadow-sm': '0 1px 2px rgb(0, 0, 0, 0.4)',
    '--shadow-md': '0 0 0 1px #e9edf51a, 0 4px 12px rgb(0, 0, 0, 0.5)',
    '--chart-1': '#4cc9b0',
  },
});
